 /* Subtle grain overlay */

  .loader-wrap {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    padding-top: 10vw;
    background: var(--bg);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 36px;
    z-index: 9999; /* Keeps it on top */
  }

  /* ── Piano mask container ── */
  .piano-mask-wrap {
    position: relative;
    width: 340px;
    height: 340px;
  }

  /* Ghost outline — always visible, faint */
  .piano-ghost {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: contain;
    opacity: 0.12;
    filter: invert(1);
  }

  /* Fill layer: rises from 0% to 100% height, masked by the piano PNG */
  .piano-fill {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    /* Use the piano as a mask so colour only shows through the illustration */
    -webkit-mask-image: url("data:image/png;base64,");
    mask-image: url('../assets/hand-drawn-piano-drawing-illustration.png');
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
    overflow: hidden;
  }

  .piano-fill-inner {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 0%;
    background: linear-gradient(
      to top,
      #c8953a 0%,
      #e8b86d 40%,
      #f5d68a 75%,
      #fff4c2 100%
    );
    transition: height 0.12s ease-out;
    box-shadow: 0 -6px 24px rgba(232, 184, 109, 0.6);
  }




  /* Shimmer on the fill */
  @keyframes shimmer {
    0%   { opacity: 0.85; }
    50%  { opacity: 1; }
    100% { opacity: 0.85; }
  }
  .piano-fill-inner {
    animation: shimmer 2s ease-in-out infinite;
  }

  /* Done state */
  .loader-wrap.done {
    transition: opacity 2s ease;
    opacity: 0;
    
  }
  .loader-wrap.done .piano-ghost {
    opacity: 0;
    transition: opacity 0.6s;
  }
  .loader-wrap.done .piano-fill-inner {
    box-shadow: 0 0 40px rgba(245, 214, 138, 0.9);
  }